"use client"

import * as React from "react"
import { DayPicker, getDefaultClassNames, type DayPickerProps } from "react-day-picker"

import { buttonVariants } from "@/components/ui/button"
import { useInk } from "@/lib/ink/react"
import { calendarPanelRecipe } from "@/lib/ink/recipes/calendar-ink"
import { cn } from "@/lib/utils"

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  seed,
  ...props
}: DayPickerProps & { seed?: string | number }) {
  const defaults = getDefaultClassNames()
  const { hostRef, hostProps, node } = useInk({
    recipe: calendarPanelRecipe,
    params: {},
    kind: "calendar",
    seed,
    still: true,
  })

  return (
    <div data-slot="calendar" className={cn("relative w-fit", className)}>
      <div
        ref={hostRef}
        {...hostProps}
        className="pointer-events-none absolute inset-0 overflow-hidden rounded-[var(--radius-md)]"
        aria-hidden
      >
        {node}
      </div>
      <DayPicker
        showOutsideDays={showOutsideDays}
        className={cn("relative z-[1] p-3 [--cell-size:2rem]")}
        classNames={{
          root: cn("w-fit", defaults.root),
          months: cn("relative flex flex-col gap-4 sm:flex-row", defaults.months),
          month: cn("flex w-full flex-col gap-3", defaults.month),
          month_caption: cn("relative flex h-8 items-center justify-center px-8", defaults.month_caption),
          caption_label: cn("text-sm font-semibold text-foreground", defaults.caption_label),
          nav: cn("absolute inset-x-0 top-0 flex items-center justify-between", defaults.nav),
          button_previous: cn(
            buttonVariants({ variant: "ghost", size: "icon" }),
            "size-8 text-muted-foreground hover:text-foreground",
            defaults.button_previous,
          ),
          button_next: cn(
            buttonVariants({ variant: "ghost", size: "icon" }),
            "size-8 text-muted-foreground hover:text-foreground",
            defaults.button_next,
          ),
          weekdays: cn("flex", defaults.weekdays),
          weekday: cn(
            "text-muted-foreground flex-1 select-none rounded-md text-[0.7rem] font-medium uppercase tracking-wide",
            defaults.weekday,
          ),
          week: cn("mt-1 flex w-full", defaults.week),
          day: cn(
            "relative flex flex-1 items-center justify-center p-0 text-center text-sm",
            defaults.day,
          ),
          day_button: cn(
            "relative size-[var(--cell-size)] rounded-md border border-transparent p-0 font-normal transition-colors",
            "text-foreground hover:border-[color-mix(in_srgb,var(--sd-pencil)_35%,transparent)]",
            "hover:bg-[color-mix(in_srgb,var(--sd-rose-wash)_22%,transparent)]",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
            "aria-selected:border-[color-mix(in_srgb,var(--sd-rose)_25%,transparent)]",
            "aria-selected:bg-[color-mix(in_srgb,var(--sd-rose-wash)_48%,transparent)]",
            "aria-selected:font-medium aria-selected:text-foreground",
            "data-[today=true]:ring-1 data-[today=true]:ring-[var(--sd-horizon)]",
            "data-[today=true]:ring-offset-1 data-[today=true]:ring-offset-[color-mix(in_srgb,var(--sd-sand-slip)_60%,transparent)]",
            "data-[outside=true]:text-muted-foreground/50 data-[outside=true]:aria-selected:bg-[color-mix(in_srgb,var(--sd-rose-wash)_28%,transparent)]",
            "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-40",
            defaults.day_button,
          ),
          selected: cn("font-medium", defaults.selected),
          today: cn("font-medium", defaults.today),
          outside: cn("text-muted-foreground/50", defaults.outside),
          disabled: cn("opacity-40", defaults.disabled),
          range_start: cn(
            "rounded-s-md bg-[color-mix(in_srgb,var(--sd-rose-wash)_48%,transparent)]",
            defaults.range_start,
          ),
          range_middle: cn(
            "rounded-none bg-[color-mix(in_srgb,var(--sd-rose-wash)_28%,transparent)]",
            defaults.range_middle,
          ),
          range_end: cn(
            "rounded-e-md bg-[color-mix(in_srgb,var(--sd-rose-wash)_48%,transparent)]",
            defaults.range_end,
          ),
          ...classNames,
        }}
        components={{
          Chevron: ({ orientation, className: chevronClass }) => (
            <span
              className={cn("inline-flex size-4 items-center justify-center text-base leading-none", chevronClass)}
              aria-hidden
            >
              {orientation === "left" ? "‹" : orientation === "right" ? "›" : orientation === "up" ? "▴" : "▾"}
            </span>
          ),
        }}
        {...props}
      />
    </div>
  )
}

export { Calendar }

import { defineRecipe } from '@/lib/ink/recipes'
import { drawCompactSandSlipPanel } from '@/lib/ink/recipes/panel-wash'

export const calendarPanelRecipe = defineRecipe<Record<string, never>>({
  id: 'calendar-panel',
  kind: 'calendar',
  layers: ['rest'],
  pad: 10,
  draw(ink, { w, h }) {
    ink.layer('rest', () => drawCompactSandSlipPanel(ink, w, h))
  },
})

import { roundRectPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import type { Ink } from '@/lib/ink/builder'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export type PanelTone = 'default' | 'lifted'

/** Compact sand-slip panel (Tooltip / Toast). */
export function drawCompactSandSlipPanel(ink: Ink, w: number, h: number) {
  const r = clamp(Math.min(w, h) * 0.1, 4, 7)
  const inset = 0.55
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: 0.82, wobble: 0.48 },
      { color: 'sand', alpha: 0.28, inset: 0.9, wobble: 0.55 },
      { color: 'wash-gold', alpha: 0.06, inset: 1.6, wobble: 0.9 },
    ])
  })
  box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
    pen: 'pencil.fine',
    corner: r,
    loose: 0.95,
    opts: { alpha: 0.48, wobble: 0.38, simple: w > 280 },
  })
  box(ink, 1.1, 1.1, w - 2.2, h - 2.2, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1,
    opts: { alpha: 0.18, wobble: 0.42, simple: true, color: 'line-soft' },
  })
}

/** Sand-slip panel fill + double loose border (Card / Dialog / Popover). */
export function drawSandSlipPanel(ink: Ink, w: number, h: number, tone: PanelTone = 'default') {
  const r = clamp(Math.min(w, h) * 0.04, 5, 12)
  const inset = 0.7
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: tone === 'lifted' ? 0.9 : 0.78, wobble: 0.5 },
      { color: 'sand', alpha: 0.32, inset: 1.2, wobble: 0.65 },
      { color: 'wash-gold', alpha: 0.08, inset: 2.4, wobble: 1.1 },
    ])
  })
  box(ink, 0.65, 0.65, w - 1.3, h - 1.3, {
    pen: 'pencil.fine',
    corner: r,
    loose: 1.15,
    opts: { alpha: 0.52, wobble: 0.42, simple: w > 420 },
  })
  box(ink, 1.4, 1.4, w - 2.8, h - 2.8, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1.25,
    opts: { alpha: 0.22, wobble: 0.5, simple: true, color: 'line-soft' },
  })
}

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
